python3 - <<'EOF'
import os
for d in ["/usr/share/fonts", "/usr/local/share/fonts", os.path.expanduser("~/.fonts")]:
    try:
        print(d, os.path.exists(d))
        if os.path.exists(d):
            for root, dirs, files in os.walk(d):
                for f in files:
                    print(os.path.join(root, f))
                if len(files) == 0 and root != d:
                    break
    except Exception as e:
        print(d, "err", e)
EOF
